// A release seal drawn from paths, circles and text. Ribbon tails go first so
// the rosette covers their tops; the lettering around the ring is one text
// element per character, rotated into place.
const S = 640, c = S / 2;
const font = "Inter, 'Helvetica Neue', Arial, sans-serif";
const stop = (offset, color, opacity = 1) => ({ name: "stop", attributes: { offset, "stop-color": color, "stop-opacity": opacity } });
const r2 = (n) => Math.round(n * 100) / 100;

const defs = { name: "defs", children: [
  { name: "linearGradient", attributes: { id: "gold", x1: "0%", y1: "0%", x2: "100%", y2: "100%" }, children: [stop("0%", "#fff3c4"), stop("30%", "#f2c14e"), stop("60%", "#c98a1b"), stop("100%", "#ffe08a")] },
  { name: "radialGradient", attributes: { id: "face", cx: "40%", cy: "35%", r: "75%" }, children: [stop("0%", "#2b3a8f"), stop("100%", "#0d1440")] },
  { name: "linearGradient", attributes: { id: "ribbon", x1: "0%", y1: "0%", x2: "0%", y2: "100%" }, children: [stop("0%", "#e11d48"), stop("100%", "#881337")] },
  { name: "filter", attributes: { id: "shadow", x: "-20%", y: "-20%", width: "140%", height: "140%" }, children: [{ name: "feDropShadow", attributes: { dx: 0, dy: 10, stdDeviation: 14, "flood-color": "#0f172a", "flood-opacity": 0.35 } }] }
] };

// Ribbon tails with a notched end.
const tail = (x, dir) => ({ name: "path", attributes: {
  d: `M ${x} 380 L ${x + dir * 92} 380 L ${x + dir * 118} 610 L ${x + dir * 60} 572 L ${x + dir * 8} 620 Z`,
  fill: "url(#ribbon)", stroke: "#4c0519", "stroke-width": 2, "stroke-linejoin": "round"
} });

// Rosette: a closed path whose radius waves 36 times around the circle.
let d = "";
for (let i = 0; i <= 360; i++) {
  const a = (i / 360) * Math.PI * 2;
  const r = 236 + 12 * Math.cos(a * 36);
  d += `${i ? "L" : "M"} ${r2(c + Math.cos(a) * r)} ${r2(c + Math.sin(a) * r)} `;
}

// Lettering around the ring.
const phrase = "RELEASE 2.0 · SHIPPED ON TIME · BUILT WITH NODETOOL · ";
const ringR = 182;
const letters = [...phrase].map((ch, i) => {
  const deg = (i / phrase.length) * 360 - 90;
  const a = (deg * Math.PI) / 180;
  return { name: "text", attributes: {
    x: r2(c + Math.cos(a) * ringR), y: r2(c + Math.sin(a) * ringR),
    transform: `rotate(${r2(deg + 90)} ${r2(c + Math.cos(a) * ringR)} ${r2(c + Math.sin(a) * ringR)})`,
    "font-family": font, "font-size": 19, "font-weight": 700, fill: "#fde68a", "text-anchor": "middle", "dominant-baseline": "central"
  }, content: ch };
});

// Small stars between the inner rings.
const star = (x, y, r) => {
  let p = "";
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2 - Math.PI / 2, rr = i % 2 ? r * 0.45 : r;
    p += `${i ? "L" : "M"} ${r2(x + Math.cos(a) * rr)} ${r2(y + Math.sin(a) * rr)} `;
  }
  return { name: "path", attributes: { d: p + "Z", fill: "#fde68a" } };
};

return { output: [
  defs,
  tail(c - 70, -1),
  tail(c + 70, 1),
  { name: "path", attributes: { d: d + "Z", fill: "url(#gold)", filter: "url(#shadow)" } },
  { name: "circle", attributes: { cx: c, cy: c, r: 214, fill: "none", stroke: "#8a5a0b", "stroke-width": 2, opacity: 0.6 } },
  { name: "circle", attributes: { cx: c, cy: c, r: 206, fill: "url(#face)" } },
  { name: "circle", attributes: { cx: c, cy: c, r: 198, fill: "none", stroke: "#fde68a", "stroke-width": 1.5, "stroke-dasharray": "2 6", opacity: 0.8 } },
  ...letters,
  { name: "circle", attributes: { cx: c, cy: c, r: 158, fill: "none", stroke: "#fde68a", "stroke-width": 2 } },
  { name: "circle", attributes: { cx: c, cy: c, r: 150, fill: "none", stroke: "#fde68a", "stroke-width": 0.8, opacity: 0.6 } },
  { name: "circle", attributes: { cx: c, cy: c - 46, r: 44, fill: "#22c55e", stroke: "#bbf7d0", "stroke-width": 3 } },
  { name: "path", attributes: { d: `M ${c - 20} ${c - 46} L ${c - 5} ${c - 30} L ${c + 22} ${c - 62}`, fill: "none", stroke: "#ffffff", "stroke-width": 9, "stroke-linecap": "round", "stroke-linejoin": "round" } },
  { name: "text", attributes: { x: c, y: c + 48, "font-family": font, "font-size": 58, "font-weight": 900, fill: "#ffffff", "text-anchor": "middle", "letter-spacing": 2 }, content: "SHIPPED" },
  { name: "line", attributes: { x1: c - 96, y1: c + 72, x2: c + 96, y2: c + 72, stroke: "#fde68a", "stroke-width": 1.5 } },
  { name: "text", attributes: { x: c, y: c + 100, "font-family": font, "font-size": 18, "font-weight": 600, fill: "#c7d2fe", "text-anchor": "middle", "letter-spacing": 6 }, content: "OCT · 2026" },
  star(c - 100, c - 46, 10), star(c + 100, c - 46, 10)
] };
